{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello आपको Azelaic Acid cream generic की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "Yes Ma'am."
    },
    {
      "i": 2,
      "speaker": "caller",
      "text": "बोलो जी इसका price कितना है?"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "आप जिस seller को call कर रहे थे वो available नहीं है और मैं IndiaMART से बोल रही हूं।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "Price आप seller से discuss कर सकते हैं।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "पहले quantity बता दीजिए कितने piece या pack चाहिए।"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "इसमें हमको one piece चाहिए।"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "समझ गई।"
    },
    {
      "i": 8,
      "speaker": "caller",
      "text": "चलिए अब strength की बात कर लेते हैं।"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "आपको 10% weight by weight चाहिए ना?"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "Yes ma'am."
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "ठीक है।"
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "आप अपनी city और state भी बता दीजिए please।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "तो घर पर आएगा ना आपके?"
    },
    {
      "i": 14,
      "speaker": "caller",
      "text": "मैं आपके घर नहीं आ सकती बस अपनी city और state बता दीजिए seller details भेज दूंगी।"
    }
  ]
}
